public void initFromUPSItemBasePriceSim(UPSItemBasePriceSim _itemBasePriceSim)
{
    PriceConvertFactory priceConvertFactory = PriceConvertFactory::newItemPriceByUPSItemBasePriceSim(_itemBasePriceSim);

    priceConvertFactory.parmNewUnitId(this.UnitId);
    priceConvertFactory.parmRounding(true);
    priceConvertFactory.parmInventDimId(_itemBasePriceSim.InventDimId);

    PriceConvert priceConvert = priceConvertFactory.priceConvert();

    this.Price          = priceConvert.parmPrice();
    this.PriceUnit      = priceConvert.parmPriceUnit();
    this.Markup         = priceConvert.parmMarkup();
    this.PriceQty       = priceConvert.parmPriceQty();
    this.PriceDate      = _itemBasePriceSim.FromDate;
    this.AllocateMarkup = _itemBasePriceSim.PriceAllocateMarkup;

}
